import { isUndefined } from "../../util/isUndefined";
export function diffArrays(oldArray, newArray, keyFn = (e) => e) {
    const map = new Map();
    oldArray.forEach((item) => {
        const key = keyFn(item);
        map.set(key, item);
    });
    const added = [];
    const changed = [];
    const unchanged = [];
    newArray.forEach((item) => {
        const key = keyFn(item);
        const oldItem = map.get(key);
        if (isUndefined(oldItem)) {
            added.push(item);
        }
        else {
            map.delete(key);
            if (item === oldItem) {
                unchanged.push(item);
            }
            else {
                changed.push({ before: oldItem, after: item });
            }
        }
    });
    const removed = Array.from(map.values());
    return {
        added,
        changed,
        unchanged,
        removed,
    };
}
